class Solution:
    def numberOfSubarrays(self, nums: list[int], k: int) -> int:
        def atMost(k):
            left = result = odds = 0
            for right in range(len(nums)):
                if nums[right] % 2 == 1:
                    odds += 1
                while odds > k:
                    if nums[left] % 2 == 1:
                        odds -= 1
                    left += 1
                result += right - left + 1
            return result
        return atMost(k) - atMost(k - 1)

